import os

class FileHandler:
    @staticmethod
    def append_text_to_file(file_name, text_buffer, encoding, overwrite=False):
        # Check if the file exists and decide whether to append or overwrite
        if overwrite or not os.path.exists(file_name):
            # Open the file in binary write mode
            with open(file_name, 'wb' if overwrite else 'ab', encoding=encoding) as file:
                # Write the text buffer to the file
                file.write(text_buffer.encode(encoding))
                return file.tell()  # Return the number of bytes written
        return -1  # Return -1 if the file is password protected or permanently unavailable

