def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Check if the input list is empty or has only one class
    if not classes or len(classes) == 1:
        return classes

    def base_comparator(base1, base2):
        # Compare the two bases by their length
        return len(base2) - len(base1)

    # Sort the classes based on the custom comparator
    classes.sort(cmp=base_comparator)
    return classes

