def namesAndDescriptions(self, all=False):
    """
    Return attribute names and descriptions defined by interface.

    Parameters:
        all (bool, optional): If True, return all attribute information, include private attributes.
                            Otherwise, return only public attributes.
                            Default: False.

    Returns:
        dict: A dictionary where keys are attribute names and values are descriptive text about the attribute.
    """
    result = {}
    for attr_name, value in self.__dict__.items():
        try:
            attr_desc = getattr(self, f'__{attr_name}_description')
        except AttributeError:
            attr_desc = None

        if all or not attr_name.startswith('_'):
            result[attr_name] = attr_desc

    return result

