def _normalizeargs(sequence, output=None):
    # Check if the sequence is not None and is iterable
    if sequence is None:
        raise ValueError("Sequence cannot be None")
    if not hasattr(sequence, '__iter__'):
        raise TypeError("Sequence must be iterable")

    # If output is None, initialize it
    if output is None:
        output = {}

    for item in sequence:
        # Check if the item is an interface or a tuple
        if isinstance(item, type) and issubclass(item, type):
            # Extract the name from the interface
            name = item.__name__
            # Add to the output
            output[name] = None
        elif isinstance(item, tuple) and all(isinstance(i, type) for i in item):
            # Extract the name from the interface
            name = item[0].__name__
            # Add to the output
            output[name] = None
        elif isinstance(item, type):
            # Extract the name from the interface
            name = item.__name__
            # Add to the output
            output[name] = None
        else:
            # Expand individual interfaces or implements specs
            output.update(item.__dict__)
            # Collect further nested interfaces or implements specs
            subinterfaces = item.__bases__
            for subinterface in subinterfaces:
                output.update(_normalizeargs(subinterface))

    return output

