def integral(bins, edges):
    if not all(isinstance(x, (int, float)) for x in bins) or not isinstance(edges, list):
        raise ValueError("Invalid input types. 'bins' must be a list of numbers, and 'edges' must be a list of numbers without gaps.")

    if len(bins) != len(edges):
        raise ValueError("The lengths of 'bins' and 'edges' must be the same.")

    integral = []
    for i in range(len(bins) - 1):
        integral.append((edges[i + 1] - edges[i]) * bins[i])
    integral.append((edges[-1] - edges[-2]) * bins[-1])

    return integral

