from abc import ABC, abstractmethod

class Renderer(ABC):
    @abstractmethod
    def add_rendition(self, lang, file_path):
        pass


class LocalRenderer(Renderer):
    def __init__(self, translation_dict):
        self.translation_dict = translation_dict

    def remove_extension(self, file_path):
        if not file_path.endswith((".pdf", ".docx", ".doc")):
            raise ValueError(f"{file_path} has an incorrect extension")
        return file_path[:-4]

    def add_rendition(self, lang, file_path):
        original_file = self.remove_extension(file_path)
        translation_key = f"{original_file}.{lang}"
        translation_file = self.translation_dict.get(translation_key)
        if not translation_file:
            raise FileNotFoundError(f"No translation found for {translation_key}")
        result = {
            "original": original_file,
            lang: translation_file
        }
        return result

