import rdflib

def find_roots(graph: rdflib.Graph, prop: rdflib.URIRef, roots: Optional[Set["rdflib.nodes.Node"]] = None) -> Set["rdflib.nodes.Node"]:
    if roots is None:
        roots = set()

    if not graph:
        return roots

    for subject, predicate, object in graph:
        if predicate == prop and object not in roots:
            roots.add(object)

    for subject in roots:
        roots.update(find_roots(graph, prop, {object for object in graph if object in roots}))

    return roots

