        if iface.providedBy(candidate):
            return True

    elif not iface.providedBy(candidate):
        incorrect.append(f"{candidate.__name__} does not provide {iface.__name__}")

    try:
        candidate.implementedBy(iface)
    except zope.interface.Invalid as e:
        incorrect.append(str(e))

    provided_attrs = iface.providedBy(candidate)
    candidate_class = candidate.__class__
    methods = candidate_class.__dict__.keys()

    for name, value in candidate_class.__dict__.items():
