        elif callable(value) and hasattr(value, '__self__'):
            if value.__self__ is candidate:
                methods.remove(name)
            elif name in provided_attrs:
                methods.remove(name)

    if incorrect:
        if len(incorrect) == 1:
            raise incorrect[0]
        else:
