import subprocess

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    # Construct the full path to the ansible-playbook command
    playbook_command = ['ansible-playbook', playbook_path]

    # Set the extra_vars if provided
    if extra_vars:
        playbook_command.extend(['--extra-vars', extra_vars])

    # Add Ansible verbosity if provided
    if verbose:
        playbook_command.extend(['--verbose', verbose])

    # Add ansible-playbook arguments if provided
    if ansible_args:
        playbook_command.extend([f'--{key}' for key, value in ansible_args.items()])

    # Execute the ansible-playbook command
    try:
        result = subprocess.run(playbook_command, capture_output=True, text=True, check=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        if e.stderr:
            return e.stderr
        else:
            return f"Command '{playbook_command}' failed with exit code {e.returncode}"

